class Gradebook:
    """
    A gradebook for a university course.

    Attributes:
    assignments (dict): A dictionary of assignments with their weights and kinds.
    grades (dict): A dictionary of students with their recorded grades.
    """

    def __init__(self) -> None:
        """
        Initialize the gradebook.
        """
        self.assignments = {}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """
        Add an assignment to the gradebook.

        Args:
        name (str): The name of the assignment.
        weight (float): The weight of the assignment.
        kind (str, optional): The kind of the assignment. Defaults to "homework".
        """
        if kind not in ["homework", "quiz"]:
            raise ValueError("Invalid kind. Kind must be 'homework' or 'quiz'.")
        self.assignments[name] = {"weight": weight, "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        """
        Record a grade for a student in an assignment.

        Args:
        student (str): The name of the student.
        assignment (str): The name of the assignment.
        grade (float): The grade of the student in the assignment.

        Raises:
        ValueError: If the grade is outside the scale 2.0 to 5.0.
        """
        if grade < 2.0 or grade > 5.0:
            raise ValueError("Invalid grade. Grade must be between 2.0 and 5.0.")
        if student not in self.grades:
            self.grades[student] = {}
        if assignment not in self.grades[student]:
            self.grades[student][assignment] = grade
        else:
            self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        """
        Calculate the average grade of a student.

        Args:
        student (str): The name of the student.

        Returns:
        float: The average grade of the student, rounded to two decimal places.
        """
        if student not in self.grades:
            return 0.0
        total_weight = 0
        total_grade = 0
        quiz_grades = []
        for assignment, grade in self.grades[student].items():
            if self.assignments[assignment]["kind"] == "quiz":
                quiz_grades.append(grade)
            else:
                total_weight += self.assignments[assignment]["weight"]
                total_grade += grade * self.assignments[assignment]["weight"]
        if quiz_grades:
            quiz_grades.sort()
            if len(quiz_grades) > 1:
                quiz_grades = quiz_grades[1:]
            for quiz_grade in quiz_grades:
                total_weight += self.assignments[next(assignment for assignment, values in self.assignments.items() if values["kind"] == "quiz")]["weight"]
                total_grade += quiz_grade * self.assignments[next(assignment for assignment, values in self.assignments.items() if values["kind"] == "quiz")]["weight"]
        if total_weight == 0:
            return 0.0
        return round(total_grade / total_weight, 2)
